274	    /**
275	     * The deterministic, shared household id this owner maps to, derived from its last
276	     * name and postcode so that owners sharing both belong to the same household.
277	     */
278	    private String householdIdFor(Owner owner) {
279	        return householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
280	    }
