282	    /**
283	     * Size of the household this new owner will belong to once persisted: the owners
284	     * already sharing its household id, plus the owner itself. An owner with no shared
285	     * household id stands alone, so its household size is one.
286	     */
287	    private int householdSizeIncluding(Owner owner) {
288	        if (owner.getHouseholdId() == null) {
289	            return 1;
290	        }
291	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
292	    }
293	
294	    /**
295	     * Count the existing owners that already share the given first and last name,
296	     * compared case-insensitively. Used to stamp a new owner's namesake count at
297	     * registration, before it is itself persisted.
298	     */
299	    private int countNamesakes(String firstName, String lastName) {
300	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
301	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
302	            .count();
303	    }
304	
305	    /**
306	     * The existing owners that already belong to this owner's household, i.e. the persisted
307	     * owners sharing its computed household id. An owner with no household id (that maps to no
308	     * shared household) has no existing household members. As the household id is derived from
309	     * the last name, the candidates are narrowed by last name before the id is matched.
310	     */
311	    private List<Owner> existingHouseholdMembers(Owner owner) {
312	        String householdId = owner.getHouseholdId();
313	        if (householdId == null) {
314	            return List.of();
315	        }
316	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
317	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
318	            .toList();
319	    }
320	
321	    /**
322	     * The ceiling to stamp on a new owner's membership level: one above the highest membership
323	     * level currently held by an existing member of its household, so the new owner's level
324	     * cannot exceed one above the household maximum. Null when the owner has no existing
325	     * household member, in which case no ceiling applies. See {@link Owner#getMembershipLevel()}.
326	     */
327	    private Integer membershipLevelCapFor(Owner owner) {
328	        return existingHouseholdMembers(owner).stream()
329	            .map(Owner::getMembershipLevel)
330	            .max(Comparator.naturalOrder())
331	            .map(max -> max + 1)
332	            .orElse(null);
333	    }
334	
335	    /**
336	     * Find the existing owner, if any, that this new owner is a possible (soft) duplicate of:
337	     * a live owner that is not a hard duplicate (its {@link Owner#getIdentityKey() identity
338	     * key} differs) yet shares the new owner's phonetic last name (see {@link Soundex}) and
339	     * postcode. When several match, the earliest (lowest id) is chosen. An owner with no
340	     * postcode belongs to no such group, and one that deliberately declared it shares a
341	     * household is never a suspected duplicate.
342	     */
343	    private Optional<Owner> findPossibleDuplicate(Owner owner) {
344	        String postcode = owner.getPostcode();
345	        if (owner.isDeclaredHouseholdMember() || postcode == null || postcode.isBlank()) {
346	            return Optional.empty();
347	        }
348	        String identityKey = owner.getIdentityKey();
349	        return liveOwnersSoundingLike(owner).stream()
350	            .filter(existing -> postcode.equals(existing.getPostcode()))
351	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
352	            .min(Comparator.comparing(Owner::getId));
353	    }
