355	    /**
356	     * The live (non-deleted) owners whose last name sounds like this owner's, i.e. shares its
357	     * Soundex code. This is the shared candidate set for both hard-duplicate detection and the
358	     * soft match, which group owners by the phonetic sound of the last name (as the identity
359	     * key does) rather than by an exact last-name match.
360	     */
361	    private List<Owner> liveOwnersSoundingLike(Owner owner) {
362	        String soundex = Soundex.of(owner.getLastName());
363	        return ownerRepository.findByDeletedFalse().stream()
364	            .filter(existing -> soundex.equals(Soundex.of(existing.getLastName())))
365	            .toList();
366	    }
