package org.springframework.samples.petclinic.model;

import org.springframework.core.style.ToStringCreator;

import jakarta.persistence.*;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Pattern;

import java.time.LocalDate;
import java.util.*;

/**
 * Simple JavaBean domain object representing an owner.
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 */
@Entity
@Table(name = "owners")
public class Owner extends Person {
    @Column(name = "title")
    private String title;

    @Column(name = "address")
    @NotEmpty
    private String address;

    @Column(name = "address_line1")
    private String addressLine1;

    @Column(name = "address_line2")
    private String addressLine2;

    @Column(name = "city")
    @NotEmpty
    private String city;

    @Column(name = "telephone")
    @NotEmpty
    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
    private String telephone;

    @Column(name = "email")
    private String email;

    @Column(name = "registration_date")
    private LocalDate registrationDate;

    @Column(name = "birth_date")
    private LocalDate birthDate;

    @Column(name = "customer_code")
    private String customerCode;

    @Column(name = "household_id")
    private String householdId;

    @Column(name = "namesake_count")
    private Integer namesakeCount;

    @Column(name = "bulk_signup_warning")
    private Boolean bulkSignupWarning;

    @Column(name = "household_size")
    private Integer householdSize;

    @Column(name = "postcode")
    private String postcode;

    @Column(name = "possible_duplicate")
    private Boolean possibleDuplicate;

    @Column(name = "possible_duplicate_of")
    private Integer possibleDuplicateOf;

    @Column(name = "deleted", nullable = false)
    private boolean deleted;

    @Column(name = "membership_level_cap")
    private Integer membershipLevelCap;

    @Transient
    private boolean declaredHouseholdMember;

    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
    private Set<Pet> pets;

    public String getTitle() {
        return this.title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    /**
     * The owner's salutation: the {@link #getTitle() title} and last name separated by a
     * single space (e.g. {@code "DR Who"}), or just the last name when no title is on file.
     * Derived from the owner's own fields, so it stays consistent with them.
     */
    @Transient
    public String getSalutation() {
        if (this.title == null || this.title.isEmpty()) {
            return this.getLastName();
        }
        return this.title + " " + this.getLastName();
    }

    public String getAddress() {
        return this.address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getAddressLine1() {
        return this.addressLine1;
    }

    public void setAddressLine1(String addressLine1) {
        this.addressLine1 = addressLine1;
    }

    public String getAddressLine2() {
        return this.addressLine2;
    }

    public void setAddressLine2(String addressLine2) {
        this.addressLine2 = addressLine2;
    }

    public String getCity() {
        return this.city;
    }

    public void setCity(String city) {
        this.city = city;
    }

    public String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    public void setCustomerCode(String customerCode) {
        this.customerCode = customerCode;
    }

    /**
     * The owner's primary identifier: the single value that identifies the owner across
     * the system, currently the {@link #getCustomerCode() customer code}. Callers that
     * need "the owner's identity" (such as the audit trail) should read this rather than
     * the customer code directly, so that when the customer code is later unified into the
     * member id the identifier follows in one place.
     */
    @Transient
    public String getPrimaryIdentifier() {
        return this.customerCode;
    }

    public String getHouseholdId() {
        return this.householdId;
    }

    public void setHouseholdId(String householdId) {
        this.householdId = householdId;
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    public Boolean getBulkSignupWarning() {
        return this.bulkSignupWarning;
    }

    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
        this.bulkSignupWarning = bulkSignupWarning;
    }

    public Integer getHouseholdSize() {
        return this.householdSize;
    }

    public void setHouseholdSize(Integer householdSize) {
        this.householdSize = householdSize;
    }

    public String getPostcode() {
        return this.postcode;
    }

    public void setPostcode(String postcode) {
        this.postcode = postcode;
    }

    /**
     * Whether this owner deliberately declared, when created, that it shares its
     * household with an existing owner (the request's {@code sharesHousehold} flag).
     * A declared member is created despite occupying an existing household and is not
     * treated as a suspected duplicate. This is a request-scoped flag, not persisted.
     */
    @Transient
    public boolean isDeclaredHouseholdMember() {
        return this.declaredHouseholdMember;
    }

    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
        this.declaredHouseholdMember = declaredHouseholdMember;
    }

    /**
     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
     * existing owner: not a hard duplicate, but sharing that owner's phonetic last name
     * (see {@link Soundex}) and postcode while its {@link #getIdentityKey() identity key}
     * differs. See {@link #getPossibleDuplicateOf()}.
     */
    public Boolean getPossibleDuplicate() {
        return this.possibleDuplicate;
    }

    public void setPossibleDuplicate(Boolean possibleDuplicate) {
        this.possibleDuplicate = possibleDuplicate;
    }

    /**
     * The id of the existing owner this owner was flagged as a possible duplicate of, or
     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
     */
    public Integer getPossibleDuplicateOf() {
        return this.possibleDuplicateOf;
    }

    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
        this.possibleDuplicateOf = possibleDuplicateOf;
    }

    /**
     * Whether this owner has been soft-deleted. A newly created owner is {@code false};
     * deleting the owner retains its row and flags it {@code true}. A deleted owner is
     * still retrievable but is ignored by the create endpoint's duplicate/identity checks.
     */
    public boolean isDeleted() {
        return this.deleted;
    }

    public void setDeleted(boolean deleted) {
        this.deleted = deleted;
    }

    /**
     * The ceiling on this owner's {@link #getMembershipLevel() membership level}, stamped
     * when the owner is created as one above the highest membership level then held by an
     * existing member of its household, or null when the owner had no existing household
     * member and so is subject to no ceiling. See {@link #getMembershipLevel()}.
     */
    public Integer getMembershipLevelCap() {
        return this.membershipLevelCap;
    }

    public void setMembershipLevelCap(Integer membershipLevelCap) {
        this.membershipLevelCap = membershipLevelCap;
    }

    /**
     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
     * is the last two digits of the registration date's fiscal year (see {@link FiscalYear};
     * e.g. {@code "NSW-1A2B3C4D-M26"}). Derived from the owner's own fields, so it stays
     * consistent with them, including its {@link #getFiscalYear() fiscal year}.
     */
    @Transient
    public String getMembershipNumber() {
        if (this.customerCode == null || this.registrationDate == null) {
            return null;
        }
        return String.format("%s-M%02d", this.customerCode, FiscalYear.shortYearOf(this.registrationDate));
    }

    /**
     * The owner's fiscal year: the {@code 'FY<YY>'} label of the fiscal year (which starts
     * on 1 July) that their business-day-adjusted registration date falls in (see
     * {@link FiscalYear}). Derived from the owner's own registration date, so it stays
     * consistent with it; null until a registration date is on file.
     */
    @Transient
    public String getFiscalYear() {
        if (this.registrationDate == null) {
            return null;
        }
        return FiscalYear.labelFor(this.registrationDate);
    }

    /**
     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
     * over the digits of the customer code. Derived from the owner's own customer code,
     * so it stays consistent with it.
     */
    @Transient
    public Integer getCheckDigit() {
        if (this.customerCode == null) {
            return null;
        }
        return LuhnCheckDigit.of(this.customerCode);
    }

    /**
     * The owner's membership points, starting at zero: two points are added when an email is
     * on file, one more when the owner is unique (namesake count of zero), two more for a
     * household of three or more, and three more when the owner has accrued more than a fiscal
     * year of tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays
     * consistent with them.
     */
